// THE HQ'S INFECTED: their pictures, generated by code like everything in
// textures.js (whose helpers these use). The behaviour is in infected.js.
//
// THE SUIT: an office worker the plant virus has taken. Charcoal suit, white
// shirt, red tie, a lanyard with an ID card still round its neck, its head
// lolling to one side. The infection shows on it: grey-green skin, moss
// growing on the cloth, mushroom caps sprouting from its skull, and glowing
// pustules, so in a dark office you see the glow before you see the man.
//
// Same layout as a robot (ROBOT_FRAMES): frames[view][pose], 64x64, feet on
// the bottom row. Poses: stand, walk1, walk2, and two seen only from the
// front (it faces you throughout):
//   grab    both arms out, reaching for you
//   rise    getting up again: on its knees, hands on the floor
// And lying on the floor: DOWNED_TEXTURES (it will get up: still, and
// twitching as it's about to) and its corpse (finished off for good).

const SUIT_CLOTH = [52, 56, 66];
const SUIT_DARK = [30, 32, 38];
const SHIRT = [206, 204, 192];
const TIE = [150, 30, 32];
const PALLOR = [150, 160, 128];
const HAIR = [56, 44, 34];
const SHOE = [22, 20, 20];
const LANYARD = [50, 90, 170];
const FUNGUS = [190, 120, 66];
const GILLS = [226, 206, 166];
const SPORE_GLOW = [210, 255, 150];
const MOSS = [70, 104, 44];

// Suit cloth, creased, with moss growing in patches.
function cloth(colour, x, y, shade, seed) {
  if (noise(x >> 2, y >> 2, seed + 7) < 0.12) return brighten(MOSS, shade * (0.8 + 0.3 * noise(x, y, seed + 8)));
  return brighten(colour, shade * (0.9 + 0.12 * noise(x >> 1, y >> 1, seed)));
}

// Infected skin: grey-green, blotched darker.
function pallor(x, y, shade) {
  return brighten(PALLOR, shade * (0.85 + 0.15 * noise(x >> 1, y >> 1, 400)));
}

// A thick line from a to b (points as [dx, y]), shaded across its width.
function suitLimb(x, y, dx, a, b, w, colour, shade, seed) {
  const d = segmentDistance(dx, y, a[0], a[1], b[0], b[1]);
  if (d >= w) return null;
  return colour === PALLOR ? pallor(x, y, shade * (1.1 - 0.4 * d / w)) : cloth(colour, x, y, shade * (1.1 - 0.4 * d / w), seed);
}

// A mushroom cap, domed, with its pale gills showing underneath.
function mushroom(dx, y, cx, cy, r) {
  const u = (dx - cx) / r, v = (y + 0.5 - cy) / (r * 0.6);
  if (v <= 0 && u * u + v * v < 1) return brighten(FUNGUS, 1.2 - 0.4 * (u * u + v * v) - 0.2 * u);
  if (v > 0 && v < 0.5 && Math.abs(u) < 0.9) return GILLS;
  if (v >= 0.5 && v < 1.6 && Math.abs(u) < 0.22) return brighten(GILLS, 0.85); // the stalk
  return null;
}

// An arm: sleeve from shoulder to elbow and elbow to wrist, a white cuff, a hand.
function suitArm(x, y, dx, shoulder, elbow, hand, shade) {
  const h = inEllipse(dx, y, hand[0], hand[1], 2.3, 2.3);
  if (h !== null) return pallor(x, y, shade * (1.1 - 0.4 * h));
  const wx = hand[0] + (elbow[0] - hand[0]) * 0.25, wy = hand[1] + (elbow[1] - hand[1]) * 0.25;
  if (segmentDistance(dx, y, hand[0], hand[1], wx, wy) < 2.2) return brighten(SHIRT, shade); // the cuff
  return suitLimb(x, y, dx, elbow, [wx, wy], 2.6, SUIT_CLOTH, shade, 401) ||
         suitLimb(x, y, dx, shoulder, elbow, 2.9, SUIT_CLOTH, shade, 402);
}

// A leg: trousers from hip to knee to ankle, and a black office shoe.
function suitLeg(x, y, dx, hip, knee, ankle, toes, shade) {
  if (y >= ankle[1] && y < ankle[1] + 3 && dx > Math.min(ankle[0], ankle[0] + toes) - 2.5 && dx < Math.max(ankle[0], ankle[0] + toes) + 2.5) {
    return brighten(SHOE, y === ankle[1] ? 2 : 1); // the shine across the top
  }
  return suitLimb(x, y, dx, knee, ankle, 3, SUIT_CLOTH, shade * 0.9, 403) ||
         suitLimb(x, y, dx, hip, knee, 3.3, SUIT_CLOTH, shade * 0.9, 404);
}

// From the front or the back.
function suitFrontBackShape(view, pose) {
  const front = view === 'front';
  const drop = pose === 'rise' ? 10 : 0; // on its knees
  const tilt = front ? 2 : -2;           // the head lolls to one side
  return (x, y) => {
    const dx = x + 0.5 - 32;
    const yy = y - drop;

    // Arms, in front of the body when they're reaching for you.
    const arms = [];
    for (const side of [-1, 1]) {
      const sway = pose === 'walk1' ? side * 1.5 : pose === 'walk2' ? -side * 1.5 : 0;
      const shoulder = [side * 10, 21 + drop];
      if (pose === 'grab') arms.push([shoulder, [side * 13, 26], [side * 8, 23]]);         // reaching out at you
      else if (pose === 'rise') arms.push([shoulder, [side * 14, 45], [side * 15, 58]]);   // pushing itself up off the floor
      else arms.push([shoulder, [side * 12, 32], [side * 12 + sway, 43 - Math.abs(sway)]]); // hanging
    }
    if (pose === 'grab') {
      for (const [s, e, h] of arms) {
        // Fingers spread, clawing at you.
        for (const k of [-1.5, -0.5, 0.5, 1.5]) {
          const tipX = h[0] + k * 1.6 + Math.sign(h[0]) * 0.5, tipY = h[1] - 4.5 + Math.abs(k) * 0.6;
          if (segmentDistance(dx, y, h[0] + k * 0.9, h[1] - 1, tipX, tipY) < 0.7) return pallor(x, y, 1.05);
        }
        const arm = suitArm(x, y, dx, s, e, h, 1);
        if (arm) return arm;
      }
    }

    // Mushrooms sprouting from the skull, on the side away from the loll.
    const cap = mushroom(dx, yy, -tilt * 1.6, 8.5, 3.6) || mushroom(dx, yy, -tilt * 0.4, 7.5, 2.2);
    if (cap) return cap;

    // The head.
    const head = inEllipse(dx, yy, tilt, 12, 4.6, 5.2);
    if (head !== null) {
      if (front) {
        if (yy < 9.5 || (Math.abs(dx - tilt) > 3.6 && yy < 12)) return brighten(HAIR, 0.9 + 0.2 * noise(x, y, 405));
        if (yy >= 11 && yy < 12.5 && Math.abs(dx - tilt) > 0.8 && Math.abs(dx - tilt) < 3) return [214, 222, 196]; // milky eyes
        if (yy >= 14.5 && yy < 16.5 && Math.abs(dx - tilt - 0.3) < 1.3) return [50, 20, 22];                    // the jaw hangs slack
        if (Math.hypot(dx - tilt + 2.6, yy + 0.5 - 14.5) < 1.1) return glowing(SPORE_GLOW);                     // a pustule on the cheek
      } else if (yy < 15) {
        return brighten(HAIR, 0.9 + 0.2 * noise(x, y, 405));
      }
      return pallor(x, y, 1.1 - 0.35 * head);
    }
    if (yy >= 16 && yy < 20 && Math.abs(dx - tilt * 0.4) < 2) return pallor(x, y, 0.8); // the neck

    // The torso: shoulders rounding into a jacket.
    if (yy >= 19 && yy < 43) {
      const halfW = yy < 22 ? 7 + (yy - 19) : yy < 32 ? 10 : 10 - (yy - 32) * 0.08;
      if (Math.abs(dx) < halfW) {
        if (front) {
          const v = (yy - 19) * 0.45;                                         // the V of the jacket's opening
          if (yy >= 20 && yy < 37 && Math.abs(dx) < 1 + (yy - 20) * 0.07) return brighten(TIE, Math.abs(dx) < 0.5 ? 1.15 : 0.9);
          if (yy < 31 && Math.abs(dx) < v) return brighten(SHIRT, 0.9 + 0.1 * noise(x, y, 406));
          if (yy < 31 && Math.abs(dx) < v + 1.3) return SUIT_DARK;            // lapels
          if (Math.abs(dx) < 0.6 && (yy === 34 || yy === 38)) return SUIT_DARK; // buttons
          // The lanyard, and the ID card on it.
          if (dx > -7 && dx < -2 && yy >= 29 && yy < 34) return yy === 29 ? LANYARD : brighten(SHIRT, 1.05);
          if (yy < 29 && (segmentDistance(dx, yy, -2.5, 20, -4.5, 29) < 0.55 || segmentDistance(dx, yy, 2.5, 20, -4.5, 29) < 0.55)) return LANYARD;
        } else {
          // The jacket split down the back, and the growth bursting out of it.
          const split = Math.abs(dx + Math.sin(yy * 0.5)) < 1.5 + (yy > 24 && yy < 36 ? 2 : 0);
          if (split && yy > 22 && yy < 39) {
            return noise(x >> 1, y >> 1, 407) < 0.35 ? glowing(brighten(SPORE_GLOW, 0.8)) : brighten(MOSS, 0.9);
          }
        }
        if (noise(x >> 1, y >> 1, 408) < 0.015) return glowing(SPORE_GLOW); // pustules through the cloth
        return cloth(SUIT_CLOTH, x, y, roundShade(dx / halfW), 409);
      }
    }

    // Hanging (or floor-pressing) arms, beside the body.
    if (pose !== 'grab') {
      for (const [s, e, h] of arms) {
        const arm = suitArm(x, y, dx, s, e, h, 0.95);
        if (arm) return arm;
      }
    }

    // Legs. On its knees, the thighs come forward to the floor.
    for (const side of [-1, 1]) {
      if (pose === 'rise') {
        const leg = suitLimb(x, y, dx, [side * 5, 43 + drop - 4], [side * 6, 60], 3.4, SUIT_CLOTH, 0.85, 410);
        if (leg) return leg;
        continue;
      }
      const lift = (pose === 'walk1' && side < 0) || (pose === 'walk2' && side > 0) ? 3 : 0;
      const leg = suitLeg(x, y, dx, [side * 4.5, 42], [side * 4.8, 51 - lift], [side * 4.5, 59 - lift], 0, 1);
      if (leg) return leg;
    }
    return null;
  };
}

// Side on, facing right: stooped, head hanging forward, the near arm dangling.
function suitSideShape(pose) {
  const swing = pose === 'walk1' ? 3 : pose === 'walk2' ? -3 : 0;
  return (x, y) => {
    const dx = x + 0.5 - 32;

    const near = suitArm(x, y, dx, [1, 22], [4 + swing * 0.3, 32], [8 + swing * 0.7, 41], 1);
    if (near) return near;

    const cap = mushroom(dx, y, 3, 8.5, 3.4);
    if (cap) return cap;
    const head = inEllipse(dx, y, 6, 13, 4.5, 5);
    if (head !== null) {
      if ((dx < 5 && y < 14) || y < 10) return brighten(HAIR, 0.9 + 0.2 * noise(x, y, 405));
      if (dx >= 8 && dx < 9.5 && y >= 11 && y < 12.5) return [214, 222, 196]; // a milky eye
      if (dx >= 8.5 && y >= 15 && y < 17) return [50, 20, 22];                // slack mouth
      return pallor(x, y, 1.1 - 0.35 * head);
    }
    if (y >= 17 && y < 21 && dx > 1.5 && dx < 5.5) return pallor(x, y, 0.8); // neck, thrust forward

    // The tie, hanging forward away from the stooped chest.
    if (y >= 20 && y < 35 && segmentDistance(dx, y, 5.5, 20, 7.5 + swing * 0.2, 34) < 1.1) return TIE;
    const torso = inEllipse(dx, y, 0.5, 31, 6.5, 11.5);
    if (torso !== null) {
      if (dx > 3.5 && y < 26) return brighten(SHIRT, 0.9); // the collar and shirt front
      if (noise(x >> 1, y >> 1, 408) < 0.015) return glowing(SPORE_GLOW);
      return cloth(SUIT_CLOTH, x, y, 1.1 - 0.4 * torso, 411);
    }

    for (const [s, shade] of [[swing, 1], [-swing, 0.65]]) {
      const leg = suitLeg(x, y, dx, [0, 41], [1 + s * 0.6, 51], [s * 1.2, 59], 3, shade);
      if (leg) return leg;
    }
    const far = suitArm(x, y, dx, [-1, 22], [2 - swing * 0.3, 32], [5 - swing * 0.7, 41], 0.6);
    if (far) return far;
    return null;
  };
}

function makeSuitFrames() {
  const bake = (shape) => makeTexture(SUIT_CLOTH, shape);
  const poses = (make) => ({ stand: make('stand'), walk1: make('walk1'), walk2: make('walk2') });
  const front = (pose) => bake(suitFrontBackShape('front', pose));
  return {
    front: { ...poses(front), grab: front('grab'), rise: front('rise') },
    back:  poses((pose) => bake(suitFrontBackShape('back', pose))),
    right: poses((pose) => bake(suitSideShape(pose))),
    left:  poses((pose) => bake(mirroredShape(suitSideShape(pose), true))),
  };
}

// Lying on the floor, head to the left. `state`:
//   'down'      it will get up: pustules glowing
//   'twitch'    about to: an arm lifting, the pustules flaring
//   'finished'  for good: the growth burst open and gone grey, a drift of
//               dead spores round it
// SUIT_DOWN_AIM_ROW is the row a shot tests (combat.js): the gun aims down at it.
const SUIT_DOWN_AIM_ROW = 56;

function makeSuitDown(state) {
  const live = state !== 'finished';
  const glow = state === 'twitch' ? 1.2 : 0.8;
  const dim = (c) => live ? c : mix(c, [30, 30, 26], 0.45);
  return makeTexture(SUIT_CLOTH, (x, y) => {
    const dx = x + 0.5 - 32;
    if (state === 'twitch') {
      const arm = suitArm(x, y, dx, [-9, 53], [-7, 47], [-3, 44], 1); // reaching up off the floor
      if (arm) return arm;
    }
    const head = inEllipse(dx, y, -19, 56, 4, 3.6);
    if (head !== null) return dx < -20 || y < 54 ? dim(brighten(HAIR, 0.9)) : dim(pallor(x, y, 1.05 - 0.3 * head));
    if (y >= 52 && y < 61 && dx > -15 && dx < 5) {
      if (y >= 54 && y < 58 && dx < -6) return dim(y === 56 ? TIE : SHIRT);       // shirt front and tie, up by the collar
      if (Math.abs(dx + 4) < 3 && y < 56) {                                       // the growth bursting from its chest
        if (!live) return brighten([110, 112, 96], 0.7 + 0.3 * noise(x, y, 412)); // spent and grey
        return noise(x, y, 413) < 0.5 ? glowing(brighten(SPORE_GLOW, glow)) : MOSS;
      }
      if (live && noise(x >> 1, y >> 1, 414) < 0.03) return glowing(brighten(SPORE_GLOW, glow));
      return dim(cloth(SUIT_CLOTH, x, y, 1.05 - 0.35 * Math.abs(y - 56.5) / 4.5, 415));
    }
    if (y >= 54 && y < 60 && dx >= 5 && dx < 21) return dim(cloth(SUIT_CLOTH, x, y, y === 54 ? 1.1 : 0.85, 416)); // legs
    if (y >= 55 && y < 60 && dx >= 21 && dx < 24) return SHOE;
    if (!live && y >= 60 && y < 63 && Math.abs(dx + 2) < 24 - (62 - y) * 4 && noise(x, y, 417) < 0.6) {
      return brighten([140, 146, 110], 0.6 + 0.3 * noise(x, y, 418));                        // dead spores round it
    }
    return null;
  });
}

// THE BLOOMER: one that's gone further. It has rooted where it stood: its legs
// are a trunk, its roots spread across the floor, its arms hang as vines,
// and its head is a great closed BUD. Get close and the bud swells, splits
// with light, and bursts in a cloud of spores (spores.js). The same from
// every side, so all four views are one picture. Poses:
//   stand   the bud closed
//   swell   the bud swollen, splitting, light in the seams: your warning
//   open    burst: the petals splayed and drooping, the heart spent
// and its corpse: withered, the bud fallen.
const BUD = [168, 70, 128];
const BUD_DARK = [96, 34, 76];
const SEPAL = [70, 110, 50];
const BLOUSE = [128, 146, 170];

function bloomerShape(pose, dead) {
  const wither = (c) => dead ? mix(c, [96, 80, 60], 0.65) : c;
  return (x, y) => {
    const dx = x + 0.5 - 32;
    // The roots, spreading over the floor.
    if (y >= 52) {
      for (const [ex, ey] of [[-22, 62], [-13, 63], [-4, 63], [6, 63], [15, 63], [23, 61]]) {
        if (segmentDistance(dx, y, ex * 0.15, 52, ex, ey) < (y > 59 ? 1.1 : 1.6)) return wither(brighten(ROOT, 0.8 + 0.3 * noise(x, y, 420)));
      }
    }
    if (dead) {
      // Withered: slumped to a heap, the bud fallen beside it.
      const heap = inEllipse(dx, y, 0, 55, 9, 7);
      if (heap !== null && y < 62) return brighten([100, 84, 64], 1 - 0.4 * heap + 0.1 * noise(x, y, 421));
      const bud = inEllipse(dx, y, 13, 58, 5, 4);
      if (bud !== null) return brighten([110, 70, 70], 0.9 - 0.3 * bud);
      return null;
    }
    // Vines that were arms, hanging, with a few leaves.
    for (const side of [-1, 1]) {
      const vx = side * (8 + 4 * (y - 28) / 24) + Math.sin(y * 0.4 + side) * 1.2;
      if (y > 27 && y < 54 && Math.abs(dx - vx) < 1.2) return brighten(SEPAL, 0.8);
      if (y > 30 && y < 54 && noise(side + 2, y >> 2, 422) < 0.5 && Math.abs(dx - vx - side * 2) < 1.6 && (y & 3) < 2) return LEAF;
    }
    // The bud, where its head was.
    const swell = pose === 'swell';
    if (pose === 'open') {
      // Five petals splayed out round a spent heart, drooping.
      const cdx = dx, cdy = y + 0.5 - 17;
      const r = Math.hypot(cdx, cdy * 1.3), a = Math.atan2(cdy, cdx);
      const petal = 11 + 4 * Math.cos(5 * a);
      if (r < 3.5) return brighten([96, 72, 40], 0.8 + 0.3 * noise(x, y, 423));
      if (r < petal && cdy > -9) return brighten(BUD, 1.05 - 0.4 * (r / petal) - (Math.abs(Math.sin(5 * a / 2)) < 0.12 ? 0.25 : 0));
    } else {
      const rx = swell ? 9.5 : 7.5, ry = swell ? 12 : 10.5;
      const cy = 15;
      const u = dx / rx, v = (y + 0.5 - cy) / ry;
      const pointed = v < 0 ? u * u * (1 + 1.5 * -v) + v * v : u * u + v * v; // a teardrop, tip up
      if (pointed < 1) {
        // Seams between the petals: dark when closed, split with light when swelling.
        const seam = Math.abs(Math.sin(u * 2.4 + 0.3 * v)) < (swell ? 0.16 : 0.08);
        if (seam) return swell ? glowing(SPORE_GLOW) : BUD_DARK;
        if (y + 0.5 > cy + ry * 0.55) return brighten(SEPAL, 1 - 0.3 * Math.abs(u)); // green sepals cupping it
        return brighten(BUD, (1.15 - 0.45 * Math.abs(u) - 0.1 * v) * (0.92 + 0.12 * noise(x >> 1, y >> 1, 424)));
      }
    }
    // The body, slumped forward over its own trunk: a blouse, going green.
    const torso = inEllipse(dx, y, 0, 33, 7, 7.5);
    if (torso !== null) return noise(x >> 2, y >> 2, 425) < 0.25 ? brighten(MOSS, 0.9) : cloth(BLOUSE, x, y, 1.05 - 0.35 * torso, 426);
    // The trunk that was its legs: bark, with scraps of skirt.
    if (y >= 38 && y < 56 && Math.abs(dx) < 4.5 + (y - 38) * 0.08) {
      if (y < 44) return cloth(SUIT_DARK, x, y, 1, 427);
      return brighten(ROOT, 0.75 + 0.35 * noise(x >> 1, y, 428) - 0.25 * Math.abs(dx) / 5);
    }
    return null;
  };
}

function makeBloomerFrames() {
  const pose = (p) => makeTexture(BUD, bloomerShape(p, false));
  const stand = pose('stand');
  const views = { stand, walk1: stand, walk2: stand };
  return { front: { ...views, swell: pose('swell'), open: pose('open') }, back: views, right: views, left: views };
}

// A SPORE CLOUD (spores.js): a soft, drifting haze, yellow-green, with motes
// glowing in it. Several of these billboards together make one cloud.
const SPORE_FRAMES_COUNT = 6;
function makeSporeCloud(frame) {
  const drift = frame * 48 / SPORE_FRAMES_COUNT;
  return makeTexture([200, 210, 120], (x, y) => {
    const r = Math.hypot(x + 0.5 - 32, y + 0.5 - 36) / 27;
    if (r >= 1) return null;
    const n = 0.6 * smoothNoise(x, y + drift, 8, 48, 430) + 0.4 * smoothNoise(x + 7, y + drift * 2, 4, 48, 431);
    const density = (1 - r * r) * (0.25 + 0.75 * n);
    if (noise(x, (y + Math.floor(drift)) & 63, 432) < 0.012 && density > 0.2) return glowing([230, 255, 150]); // a mote
    if (density < 0.15) return null;
    return seeThrough(brighten([196, 206, 110], 0.8 + 0.35 * n), Math.min(150, 200 * density));
  });
}
const SPORE_FRAMES = [];
for (let f = 0; f < SPORE_FRAMES_COUNT; f++) SPORE_FRAMES.push(makeSporeCloud(f));

// SPRINKLER SPRAY (sprinklers.js): water falling from a ceiling head, fanning
// out as it falls, in streaks that scroll down, splashing at the floor.
const RAIN_FRAMES_COUNT = 4;
function makeSprinklerRain(frame) {
  return makeTexture([190, 210, 230], (x, y) => {
    const dx = x + 0.5 - 32;
    if (Math.abs(dx) > 4 + y * 0.4) return null;                               // the fan of the spray
    if (y >= 60) return noise(x, frame, 440) < 0.25 ? seeThrough([220, 235, 250], 200) : null; // splashes
    if (noise(x, 0, 441) > 0.35) return null;                                   // only some columns carry a stream
    const fall = (y + frame * 16 + Math.floor(noise(x, 1, 442) * 64)) % 16;
    return fall < 6 ? seeThrough([200, 220, 240], 140 + 15 * fall) : null;
  });
}
const RAIN_FRAMES = [];
for (let f = 0; f < RAIN_FRAMES_COUNT; f++) RAIN_FRAMES.push(makeSprinklerRain(f));

// THE POLLINATORS (pollinators.js): moths the infection has grown huge, as big as
// a dog, fat and furry. Dusty wings with a glowing green
// eyespot on each, so a swarm in the dark is a cloud of green eyes.
// MOTH_FRAMES[0] wings up, [1] wings down (it flaps between the two). They
// fly at eye height, so a shot tests them where it always does.
const MOTH_WING = [140, 120, 96];
const MOTH_FUR = [176, 156, 124];

function makeMoth(up) {
  return makeTexture(MOTH_WING, (x, y) => {
    const dx = x + 0.5 - 32, yy = y + 0.5;
    // Antennae, feathery.
    for (const s of [-1, 1]) {
      const d = segmentDistance(dx, yy, s * 1, 23, s * 6, 15);
      if (d < 0.5 || (d < 1.6 && (y & 1) === 0 && Math.abs(dx) > 2)) return brighten(MOTH_FUR, 0.7);
    }
    // The head, with its eyes.
    if (Math.hypot(dx, yy - 25) < 2.8) return Math.abs(dx) > 0.8 && yy < 25.5 ? glowing(SPORE_GLOW) : brighten(MOTH_FUR, 0.9);
    // The fat, banded body.
    const body = inEllipse(dx, y, 0, 35, 3.4, 8.5);
    if (body !== null) return brighten(MOTH_FUR, (1.15 - 0.4 * body) * ((y & 3) === 0 ? 0.75 : 1));
    // The wings: a forewing and a hindwing each side, raised or lowered.
    for (const s of [-1, 1]) {
      const tilt = s * (up ? -0.45 : 0.3);
      for (const [cx, cy, rx, ry, fore] of [[s * 12, up ? 27 : 32, 11, 6.5, true], [s * 8.5, up ? 37 : 40, 7, 4.5, false]]) {
        const ux = dx - cx, uy = yy - cy;
        const u = (ux * Math.cos(tilt) + uy * Math.sin(tilt)) / rx;
        const v = (-ux * Math.sin(tilt) + uy * Math.cos(tilt)) / ry;
        const r = u * u + v * v;
        if (r >= 1) continue;
        if (fore) {
          const spot = Math.hypot(u * rx - s * 1.5, v * ry);
          if (spot < 1.2) return [30, 26, 20];                 // the eyespot's pupil
          if (spot < 2.8) return glowing(SPORE_GLOW);          // its glowing ring
        }
        if (r > 0.75) return brighten(MOTH_WING, 0.55);         // the dark wing edge
        const band = Math.abs(Math.sin(u * 5 + v)) < 0.18;      // the wavy markings
        return brighten(MOTH_WING, (band ? 0.7 : 1) * (0.9 + 0.15 * noise(x, y, 450)));
      }
    }
    return null;
  });
}
const MOTH_FRAMES = [makeMoth(true), makeMoth(false)];

// THE MANAGER (manager.js): the one the plant took whole, mind and all.
// Upright where the suits slump: a pale grey three-piece suit, a purple
// tie, slicked hair, a PA headset with its microphone at its mouth. Its eyes
// GLOW (it's paying attention), and instead of mushrooms a crown of white
// lilies blooms from the back of its skull, their hearts glowing. Poses:
// stand, walk1, walk2, and 'root' (re-rooting in a planter: its legs gone
// to roots, spreading across the floor).
const MANAGER_CLOTH = [118, 122, 134];
const MANAGER_DARK = [74, 76, 88];
const MANAGER_TIE = [96, 50, 130];
const LILY = [236, 232, 220];
const HEADSET = [26, 26, 30];
const MANAGER_EYE = [180, 255, 140];
const MANAGER_ROOT = [86, 64, 40];

function managerLimb(x, y, dx, a, b, w, shade, seed) {
  return suitLimb(x, y, dx, a, b, w, MANAGER_CLOTH, shade, seed);
}

// The lilies: petals in a fan above and behind the head, each a narrow
// ellipse pointing out from a glowing heart.
function lilyCrown(dx, y, cx, cy) {
  for (let k = 0; k < 5; k++) {
    const a = -Math.PI / 2 + (k - 2) * 0.55;
    const px = cx + Math.cos(a) * 4, py = cy + Math.sin(a) * 4;
    const u = ((dx - px) * Math.cos(a) + (y + 0.5 - py) * Math.sin(a)) / 3.4;
    const v = (-(dx - px) * Math.sin(a) + (y + 0.5 - py) * Math.cos(a)) / 1.4;
    if (u * u + v * v < 1) return brighten(LILY, 1.05 - 0.25 * Math.abs(u));
  }
  if (Math.hypot(dx - cx, y + 0.5 - cy) < 1.6) return glowing(SPORE_GLOW);
  return null;
}

// Roots instead of legs: tendrils from the hips, out across the floor.
function managerRoots(x, y, dx) {
  for (let k = -2; k <= 2; k++) {
    if (segmentDistance(dx, y, k * 1.5, 41, k * 7 + 2 * Math.sin(k), 62) < 1.4 - 0.15 * Math.abs(k)) {
      return brighten(MANAGER_ROOT, 0.8 + 0.3 * noise(x, y, 420));
    }
  }
  if (y >= 60 && Math.abs(dx) < 20 && noise(x, y, 421) < 0.4) return brighten(MOSS, 0.8); // the moss they spread into
  return null;
}

function managerFrontBackShape(view, pose) {
  const front = view === 'front';
  return (x, y) => {
    const dx = x + 0.5 - 32;
    const crown = lilyCrown(dx, y, 0, 6);
    if (crown && (!front || y < 8)) return crown; // from the front, only the petals over the top of its head show
    const head = inEllipse(dx, y, 0, 12, 4.4, 5.2);
    if (head !== null) {
      if (Math.abs(Math.abs(dx) - 4.4) < 0.9 && y >= 10 && y < 14) return HEADSET; // the earpieces
      if (y < 9.5 || (!front && y < 15)) return brighten(HAIR, 0.6 + 0.2 * noise(x, y, 422)); // slicked back
      if (front) {
        if (y >= 11 && y < 12.5 && Math.abs(dx) > 0.8 && Math.abs(dx) < 3) return glowing(MANAGER_EYE);
        if (y >= 14.5 && y < 15.5 && Math.abs(dx) < 1.6) return [70, 40, 44];   // a thin, set mouth
        if (segmentDistance(dx, y, 4, 13, 1.5, 15.5) < 0.5) return HEADSET;     // the microphone boom
      }
      return pallor(x, y, 1.1 - 0.35 * head);
    }
    if (y >= 16 && y < 19 && Math.abs(dx) < 2) return pallor(x, y, 0.8);
    // Arms, hanging straight: it stands up properly.
    for (const side of [-1, 1]) {
      const sway = pose === 'walk1' ? side * 1.5 : pose === 'walk2' ? -side * 1.5 : 0;
      const hand = [side * 11 + sway * 0.3, 42];
      const h = inEllipse(dx, y, hand[0], hand[1], 2.1, 2.1);
      if (h !== null) return pallor(x, y, 1.05 - 0.4 * h);
      if (segmentDistance(dx, y, hand[0], hand[1] - 1, side * 11, 39) < 2) return brighten(SHIRT, 0.95);
      const arm = managerLimb(x, y, dx, [side * 9.5, 20], [side * 11, 30], 2.7, 0.95, 423) || managerLimb(x, y, dx, [side * 11, 30], [side * 11, 39], 2.5, 0.95, 424);
      if (arm) return arm;
    }
    if (y >= 18 && y < 42) {
      const halfW = y < 21 ? 6 + (y - 18) * 1.1 : 9;
      if (Math.abs(dx) < halfW) {
        if (front) {
          if (y >= 19 && y < 36 && Math.abs(dx) < 0.9 + (y - 19) * 0.05) return brighten(MANAGER_TIE, Math.abs(dx) < 0.4 ? 1.2 : 0.95);
          if (y < 27 && Math.abs(dx) < (y - 18) * 0.5) return brighten(SHIRT, 1);
          if (y < 37 && Math.abs(dx) < 5) return brighten(MANAGER_DARK, 0.95 + 0.1 * noise(x, y, 425)); // the waistcoat
          if (y < 37 && Math.abs(dx) < 6) return brighten(MANAGER_DARK, 0.7);                           // its edge, under the jacket
          if (dx > 4 && dx < 7 && y >= 24 && y < 26) return glowing(SPORE_GLOW);                         // a pocket square, gone to flower
        } else if (Math.abs(dx) < 3 && y > 22 && y < 38 && noise(x >> 1, y >> 1, 426) < 0.3) {
          return glowing(brighten(SPORE_GLOW, 0.7)); // the plant shows through the seam, faintly
        }
        return cloth(MANAGER_CLOTH, x, y, roundShade(dx / halfW), 427);
      }
    }
    if (pose === 'root') return managerRoots(x, y, dx);
    for (const side of [-1, 1]) {
      const lift = (pose === 'walk1' && side < 0) || (pose === 'walk2' && side > 0) ? 3 : 0;
      if (y >= 59 - lift && y < 62 - lift && Math.abs(dx - side * 4.5) < 2.6) return brighten(SHOE, y === 59 - lift ? 2.2 : 1);
      const leg = managerLimb(x, y, dx, [side * 4.5, 41], [side * 4.6, 50 - lift], 3, 0.9, 428) ||
                  managerLimb(x, y, dx, [side * 4.6, 50 - lift], [side * 4.5, 59 - lift], 2.8, 0.9, 429);
      if (leg) return leg;
    }
    return null;
  };
}

// Side on, facing right: straight-backed, chin up.
function managerSideShape(pose) {
  const swing = pose === 'walk1' ? 3 : pose === 'walk2' ? -3 : 0;
  return (x, y) => {
    const dx = x + 0.5 - 32;
    const crown = lilyCrown(dx, y, -3, 7);
    if (crown) return crown;
    const head = inEllipse(dx, y, 1.5, 12, 4.4, 5);
    if (head !== null) {
      if (dx < 0.5 && y < 15) return brighten(HAIR, 0.6 + 0.2 * noise(x, y, 422));
      if (Math.abs(dx - 1) < 1 && y >= 11 && y < 14) return HEADSET;
      if (dx >= 3.5 && dx < 5 && y >= 11 && y < 12.5) return glowing(MANAGER_EYE);
      if (segmentDistance(dx, y, 1.5, 13, 5.5, 15.5) < 0.5) return HEADSET;
      return pallor(x, y, 1.1 - 0.35 * head);
    }
    if (y >= 16 && y < 19 && dx > -1 && dx < 3) return pallor(x, y, 0.8);
    const near = managerLimb(x, y, dx, [1, 21], [2 + swing * 0.3, 31], 2.6, 1, 423) || managerLimb(x, y, dx, [2 + swing * 0.3, 31], [3 + swing * 0.6, 40], 2.4, 1, 424);
    if (near) return near;
    if (inEllipse(dx, y, 3 + swing * 0.6, 42, 2, 2) !== null) return pallor(x, y, 1);
    const torso = inEllipse(dx, y, 0.5, 30, 5.5, 12);
    if (torso !== null) {
      if (dx > 3 && y < 25) return brighten(SHIRT, 0.95);
      if (dx > 3.5 && y < 36) return brighten(MANAGER_TIE, 0.9);
      return cloth(MANAGER_CLOTH, x, y, 1.1 - 0.4 * torso, 427);
    }
    if (pose === 'root') return managerRoots(x, y, dx);
    for (const [s, shade] of [[swing, 1], [-swing, 0.65]]) {
      if (y >= 59 && y < 62 && dx > s * 1.2 - 1.5 && dx < s * 1.2 + 4.5) return brighten(SHOE, y === 59 ? 2.2 : 1);
      const leg = managerLimb(x, y, dx, [0, 41], [s * 0.6, 50], 3, shade * 0.9, 428) || managerLimb(x, y, dx, [s * 0.6, 50], [s * 1.2, 59], 2.8, shade * 0.9, 429);
      if (leg) return leg;
    }
    return null;
  };
}

function makeManagerFrames() {
  const bake = (shape) => makeTexture(MANAGER_CLOTH, shape);
  const poses = (make) => ({ stand: make('stand'), walk1: make('walk1'), walk2: make('walk2'), root: make('root') });
  return {
    front: poses((pose) => bake(managerFrontBackShape('front', pose))),
    back:  poses((pose) => bake(managerFrontBackShape('back', pose))),
    right: poses((pose) => bake(managerSideShape(pose))),
    left:  poses((pose) => bake(mirroredShape(managerSideShape(pose), true))),
  };
}

// Dead: face down, the lilies crushed and gone brown, the headset knocked off.
function makeManagerCorpse() {
  return makeTexture(MANAGER_CLOTH, (x, y) => {
    const dx = x + 0.5 - 32;
    if (Math.hypot(dx - 24, y + 0.5 - 60) < 2 && Math.hypot(dx - 24, y + 0.5 - 60) > 1.2) return HEADSET; // the headset, on the floor
    const head = inEllipse(dx, y, -16, 56, 4, 3.5);
    if (head !== null) return y < 56 ? brighten(HAIR, 0.6) : pallor(x, y, 0.8);
    for (let k = 0; k < 3; k++) if (inEllipse(dx, y, -22 + k * 2, 52 + k, 2.5, 1.2) !== null) return brighten([150, 120, 80], 0.9); // brown petals
    const body = inEllipse(dx, y, 2, 58, 15, 4);
    if (body !== null) return cloth(MANAGER_CLOTH, x, y, 0.8 - 0.25 * body, 430);
    if (segmentDistance(dx, y, 16, 58, 26, 61) < 2.4) return cloth(MANAGER_CLOTH, x, y, 0.7, 431); // legs
    return null;
  });
}

ROBOT_FRAMES.suit = makeSuitFrames();
ROBOT_FRAMES.bloomer = makeBloomerFrames();
ROBOT_FRAMES.manager = makeManagerFrames();
const DOWNED_TEXTURES = { suit: { down: makeSuitDown('down'), twitch: makeSuitDown('twitch') } };
CORPSE_TEXTURES.suit = makeSuitDown('finished');
CORPSE_TEXTURES.bloomer = makeTexture(BUD, bloomerShape('stand', true));
CORPSE_TEXTURES.manager = makeManagerCorpse();
